import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import './Hero.css';

const Hero = () => {
  const heroRef = useRef(null);

  useEffect(() => {
    const handleMouseMove = (e) => {
      if (!heroRef.current) return;
      
      const { clientX, clientY } = e;
      const { innerWidth, innerHeight } = window;
      
      const xPos = (clientX / innerWidth - 0.5) * 20;
      const yPos = (clientY / innerHeight - 0.5) * 20;
      
      const elements = heroRef.current.querySelectorAll('.parallax-element');
      elements.forEach((el, index) => {
        const speed = (index + 1) * 0.5;
        el.style.transform = `translate(${xPos * speed}px, ${yPos * speed}px)`;
      });
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <section id="home" className="hero-modern" ref={heroRef}>
      <div className="hero-container">
        <motion.div 
          className="hero-left-modern parallax-element"
          initial={{ opacity: 0, x: -50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8 }}
        >
          <div className="profile-section-modern">
            <div className="profile-photo-modern">
              <img src="/images/pritish-photo.jpg" alt="Pritish Jadhav" />
              <div className="profile-placeholder">PJ</div>
            </div>
          </div>
          
          <div className="hero-stats-modern">
            <motion.div 
              className="stat-card-modern"
              whileHover={{ scale: 1.05, y: -5 }}
              transition={{ type: "spring", stiffness: 300 }}
            >
              <h3>10+</h3>
              <p>Projects</p>
            </motion.div>
            <motion.div 
              className="stat-card-modern"
              whileHover={{ scale: 1.05, y: -5 }}
              transition={{ type: "spring", stiffness: 300 }}
            >
              <h3>01+</h3>
              <p>Years Exp</p>
            </motion.div>
            <motion.div 
              className="stat-card-modern"
              whileHover={{ scale: 1.05, y: -5 }}
              transition={{ type: "spring", stiffness: 300 }}
            >
              <h3>100%</h3>
              <p>Dedication</p>
            </motion.div>
          </div>
        </motion.div>
        
        <motion.div 
          className="hero-right-modern parallax-element"
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
        >
          <motion.div 
            className="hero-badge-modern"
            animate={{ y: [0, -10, 0] }}
            transition={{ duration: 2, repeat: Infinity }}
          >
            <span>🚀 Available for Work ✨</span>
          </motion.div>
          
          <div className="hero-title-modern">
            <span className="title-greeting">Hey, I'm</span>
            <h1 className="title-name-modern">
              <span className="name-part">Mr. Pritish</span>
              <span className="name-part">Jadhav</span>
            </h1>
            <p className="title-tagline-modern">Let's Build Something Brilliant.</p>
          </div>
          
          <div className="hero-roles-modern">
            <motion.span 
              className="role-badge-modern"
              whileHover={{ scale: 1.1 }}
            >
              Full Stack Developer
            </motion.span>
            <motion.span 
              className="role-badge-modern"
              whileHover={{ scale: 1.1 }}
            >
              CP Enthusiast
            </motion.span>
            <motion.span 
              className="role-badge-modern"
              whileHover={{ scale: 1.1 }}
            >
              Database Administration (DBA)
            </motion.span>
          </div>
          
          <p className="hero-description-modern">
            Passionate about creating innovative solutions with AI, Data Science, and Full Stack Development. 
            Currently leading database operations at CodeChef VIT Pune.
          </p>
          
          <div className="hero-actions-modern">
            <motion.a 
              href="#contact" 
              className="btn-morphing"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              <span>Let's Talk</span>
              <i className="fas fa-arrow-right"></i>
            </motion.a>
            <motion.a 
              href="#about" 
              className="btn-liquid"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              <span>About Me</span>
              <i className="fas fa-user"></i>
            </motion.a>
          </div>
          
          <div className="hero-social-modern">
            {[
              { icon: 'fab fa-linkedin-in', link: 'https://linkedin.com/in/pritish-jadhav', title: 'LinkedIn' },
              { icon: 'fab fa-github', link: 'https://github.com/pritishjadhav', title: 'GitHub' },
              { icon: 'fab fa-twitter', link: 'https://x.com/Pritish2006', title: 'X (Twitter)' },
              { icon: 'fab fa-instagram', link: 'https://www.instagram.com/jadhav_pritish_45', title: 'Instagram' }
            ].map((social, index) => (
              <motion.a
                key={index}
                href={social.link}
                target="_blank"
                rel="noopener noreferrer"
                className="social-icon-modern"
                title={social.title}
                whileHover={{ scale: 1.2, rotate: 360 }}
                transition={{ type: "spring", stiffness: 300 }}
              >
                <i className={social.icon}></i>
              </motion.a>
            ))}
          </div>
        </motion.div>
      </div>
      
      <div className="hero-bg-modern"></div>
    </section>
  );
};

export default Hero;
